  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const depEntries = []
  const adjacency = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) throw new CliError(`line ${lineNo}: expected task <name> <cost>`)
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) throw new CliError(`line ${lineNo}: invalid task name ${name}`)
      if (!COST_RE.test(costStr)) throw new CliError(`line ${lineNo}: cost must be a non-negative integer`)
      if (tasks.has(name)) throw new CliError(`line ${lineNo}: task ${name} is declared twice`)
      tasks.set(name, Number(costStr))
    } else if (directive === 'dep') {
      if (words.length < 3) throw new CliError(`line ${lineNo}: expected dep <name> <dependency>...`)
      const name = words[1]
      const deps = words.slice(2)
      depEntries.push({ name, deps })
      if (!adjacency.has(name)) adjacency.set(name, new Set())
      const set = adjacency.get(name)
      for (const dep of deps) set.add(dep)
    } else {
      throw new CliError(`line ${lineNo}: unknown directive ${directive}`)
    }
