 * Graph analysis: cycle detection, unlimited-worker scheduling metrics, and
 * priority-driven packing onto a fixed number of workers.
 */

function depsOf(adjacency, name) {
  return adjacency.get(name)
}

/**
 * Finds the first cycle a depth-first search discovers when it visits tasks
 * in ascending name order and, at each task, walks its dependencies in
 * ascending name order. Returns the cycle as an array of names starting and
 * ending with the re-entered task, or null when the graph is acyclic.
 */
export function findCycle(tasks, adjacency) {
  const WHITE = 0
  const GRAY = 1
  const BLACK = 2
  const state = new Map()
  const stack = []

  function dfs(node) {
    state.set(node, GRAY)
    stack.push(node)
    const deps = depsOf(adjacency, node)
    if (deps) {
      for (const dep of [...deps].sort()) {
        const depState = state.get(dep) || WHITE
        if (depState === GRAY) {
          const idx = stack.indexOf(dep)
          return stack.slice(idx).concat(dep)
        }
        if (depState === WHITE) {
          const cycle = dfs(dep)
          if (cycle) return cycle
        }
      }
    }
    stack.pop()
    state.set(node, BLACK)
    return null
  }

  for (const name of [...tasks.keys()].sort()) {
    if ((state.get(name) || WHITE) === WHITE) {
      const cycle = dfs(name)
      if (cycle) return cycle
    }
  }
  return null
}

/**
 * Computes, for every task and assuming an unlimited number of workers, the
 * wave (depth), start time, and finish time as defined by the specification.
 * Requires the graph to already be known acyclic.
 */
export function computeMetrics(tasks, adjacency) {
  const depth = new Map()
  const start = new Map()
  const finish = new Map()

  function compute(name) {
    if (finish.has(name)) return
    const deps = depsOf(adjacency, name)
    if (!deps || deps.size === 0) {
      depth.set(name, 0)
      start.set(name, 0)
    } else {
      let maxDepth = -1
      let maxFinish = 0
      for (const dep of deps) {
        compute(dep)
        maxDepth = Math.max(maxDepth, depth.get(dep))
        maxFinish = Math.max(maxFinish, finish.get(dep))
      }
      depth.set(name, maxDepth + 1)
      start.set(name, maxFinish)
    }
    finish.set(name, start.get(name) + tasks.get(name))
  }

  for (const name of tasks.keys()) compute(name)
  return { depth, start, finish }
}

/**
 * Computes the priority of every task: the cost of the longest chain that
 * begins at the task and follows its dependents down to any task nothing
 * depends on, counting every task's cost along the way.
 */
function computePriority(tasks, adjacency) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, deps] of adjacency.entries()) {
    for (const dep of deps) {
      if (!dependents.has(dep)) dependents.set(dep, [])
      dependents.get(dep).push(name)
    }
  }

  const priority = new Map()
  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const child of dependents.get(name) || []) {
      best = Math.max(best, compute(child))
    }
    const value = tasks.get(name) + best
    priority.set(name, value)
    return value
  }
  for (const name of tasks.keys()) compute(name)
  return priority
}

/**
 * Simulates the graph on a fixed number of workers, following the greedy
 * priority rule from the specification. Returns each worker's ordered run
 * log and the overall makespan.
 */
export function pack(tasks, adjacency, workers) {
  const priority = computePriority(tasks, adjacency)
  const deps = new Map()
  for (const name of tasks.keys()) deps.set(name, [...(depsOf(adjacency, name) || [])])

  const unscheduled = new Set(tasks.keys())
  const finishTime = new Map()
  const workerFreeAt = new Array(workers).fill(0)
  const workerLog = Array.from({ length: workers }, () => [])
  let currentTime = 0

  const isReady = (name, time) => deps.get(name).every((dep) => (finishTime.get(dep) ?? Infinity) <= time)

  while (unscheduled.size > 0) {
    for (;;) {
      let freeWorker = -1
      for (let i = 0; i < workers; i++) {
        if (workerFreeAt[i] <= currentTime) {
          freeWorker = i
          break
        }
      }
      if (freeWorker === -1) break

      let best = null
      for (const name of unscheduled) {
        if (!isReady(name, currentTime)) continue
        if (best === null) {
          best = name
          continue
        }
        const pBest = priority.get(best)
        const pName = priority.get(name)
        if (pName > pBest || (pName === pBest && name < best)) best = name
      }
      if (best === null) break

      const cost = tasks.get(best)
      const startTime = currentTime
      const finishAt = startTime + cost
      workerFreeAt[freeWorker] = finishAt
      workerLog[freeWorker].push({ name: best, start: startTime, finish: finishAt })
      finishTime.set(best, finishAt)
      unscheduled.delete(best)
    }

    if (unscheduled.size === 0) break

    let nextTime = Infinity
    for (let i = 0; i < workers; i++) {
      if (workerFreeAt[i] > currentTime) nextTime = Math.min(nextTime, workerFreeAt[i])
    }
    if (nextTime === Infinity) break
    currentTime = nextTime
  }

  let makespan = 0
  for (const finishAt of finishTime.values()) makespan = Math.max(makespan, finishAt)
  return { workerLog, makespan }
}
