    const d = depth.get(name)
    if (!byDepth.has(d)) byDepth.set(d, [])
    byDepth.get(d).push(name)
  }
  const maxDepth = byDepth.size ? Math.max(...byDepth.keys()) : -1
  let out = ''
  for (let k = 0; k <= maxDepth; k++) {
    const names = byDepth.get(k).slice().sort()
    out += `wave ${k}: ${names.join(' ')}\n`
  }
  out += `total ${totalOf(finish)}\n`
  return out
}

function renderExplain(tasks, depth, start, finish) {
  let out = ''
  for (const name of [...tasks.keys()].sort()) {
    out += `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}\n`
  }
  out += `total ${totalOf(finish)}\n`
  return out
}

function renderPack(workers, workerLog, makespan) {
  let out = ''
  for (let i = 0; i < workers; i++) {
    const entries = workerLog[i].map((task) => ` ${task.name}@${task.start}-${task.finish}`).join('')
    out += `worker ${i}:${entries}\n`
  }
  out += `makespan ${makespan}\n`
  return out
}

function main() {
  const args = readArgs(process.argv.slice(2))
  const input = readFileSync(0, 'utf8')

  let tasks
  let adjacency
  try {
    ;({ tasks, adjacency } = parseInput(input))
  } catch (err) {
    if (err instanceof CliError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(err.code)
    }
    throw err
  }

  const cycle = findCycle(tasks, adjacency)
  if (cycle) {
    process.stderr.write(`error: cycle: ${cycle.join(' -> ')}\n`)
    process.exit(3)
  }

  if (args.mode === 'waves') {
    const { depth, finish } = computeMetrics(tasks, adjacency)
    process.stdout.write(renderWaves(tasks, depth, finish))
  } else if (args.mode === 'explain') {
    const { depth, start, finish } = computeMetrics(tasks, adjacency)
    process.stdout.write(renderExplain(tasks, depth, start, finish))
  } else {
    const { workerLog, makespan } = pack(tasks, adjacency, args.workers)
    process.stdout.write(renderPack(args.workers, workerLog, makespan))
  }
}

main()
